import {cctvLabel} from './cctv-data.js';
import * as T from './vendor/three.module.js';
import {counterPoint} from './counter-layout.js';
import {drawBusinessScreens} from './business-world.js';
import {installFieldDevices,updateFieldDevices} from './field-devices.js';
function screen(w,name,x,y,z,width,height,rotation=0,parent=w.scene){const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=768;const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;const mesh=new T.Mesh(new T.PlaneGeometry(width,height),new T.MeshBasicMaterial({map:texture,toneMapped:false}));mesh.position.set(x,y,z);mesh.rotation.y=rotation;mesh.userData.target={id:name};parent.add(mesh);return{canvas,texture,mesh,ctx:canvas.getContext('2d')};}
export function installDiegetic(w){w.screens={terminal:screen(w,'terminal',-5.65,1.43,-1.863,.55,.40,0,w.counterRoot),monitor:screen(w,'monitor',-10.16,1.6,2.3,.42,.38,Math.PI/2),pump:screen(w,'pump',7,1.5,-11.65,.65,.35)};w.cctvTarget=new T.WebGLRenderTarget(320,240,{minFilter:T.NearestFilter,magFilter:T.NearestFilter});w.cctvCamera=new T.PerspectiveCamera(73,4/3,.1,100);const monitor=w.screens.monitor.mesh;monitor.material.transparent=true;monitor.material.depthWrite=false;w.monitorFeed=new T.Mesh(monitor.geometry,new T.MeshBasicMaterial({map:w.cctvTarget.texture,toneMapped:false}));w.monitorFeed.position.copy(monitor.position).add(new T.Vector3(-.002,0,0));w.monitorFeed.rotation.copy(monitor.rotation);w.scene.add(w.monitorFeed);w.wires={};installFieldDevices(w);w.device=null;w.deviceSelection=0;w.deviceResult='';w.focusMix=0;w.screenStamp='';}
export const registryEntries=s=>s.cast?.filter(c=>s.ids.includes(c.id)||s.talked.includes(c.id))||[];
export function drawScreens(w,s){if(s.campaign&&w.screens.register)drawBusinessScreens(w,s);}
export function updateDiegetic(w,s,dt){const stamp=JSON.stringify([s.power,s.talked,s.ids,s.pumpChecked,s.pumpDone,w.deviceSelection,w.deviceResult]);if(stamp!==w.screenStamp){w.screenStamp=stamp;drawScreens(w,s);}const out=w.screens.monitor;const monitorPosition=out.mesh.getWorldPosition(new T.Vector3()),direction=new T.Vector3(0,0,-1).applyQuaternion(w.camera.quaternion),to=monitorPosition.clone().sub(w.camera.position);const looking=to.length()<3&&to.normalize().dot(direction)>.84;
 if(s.power&&(w.device==='monitor'||looking)&&(w.feedState!==s||w.lastFeedCamera!==w.cameraIndex||w.lastFeedBus!==!!s.narrative?.flags.busArrived||s.time<(w.feedTime??-99)||s.time-(w.feedTime??-99)>(w.device==='monitor'?.25:1))){w.feedPending=w.cameraIndex||0;w.feedTime=s.time;w.feedState=s;w.lastFeedCamera=w.cameraIndex;w.lastFeedBus=!!s.narrative?.flags.busArrived;}
 if(w.monitorPower!==s.power||w.monitorLabel!==w.cameraIndex||w.monitorBus!==!!s.narrative?.flags.busArrived){w.monitorPower=s.power;w.monitorLabel=w.cameraIndex;w.monitorBus=!!s.narrative?.flags.busArrived;out.ctx.clearRect(0,0,1024,768);if(!s.power){out.ctx.fillStyle='#07120c';out.ctx.fillRect(0,0,1024,768);out.ctx.fillStyle='#a5ba93';out.ctx.font='48px monospace';out.ctx.fillText('NO SIGNAL',230,390);}else{out.ctx.fillStyle='#c2d9a5';out.ctx.font='34px monospace';out.ctx.fillText(cctvLabel(w.cameraIndex||0,!!s.narrative?.flags.busArrived),35,55);out.ctx.font='24px monospace';out.ctx.fillText('1 店内 / 2 后仓 / 3 后场 / 4 前场 · Q 离开',35,730);}out.texture.needsUpdate=true;}w.monitorFeed.visible=!!s.power;

 w.focusMix=T.MathUtils.damp(w.focusMix,w.device?1:0,12,dt||.016);const regA=counterPoint(-8.75,2.15,-.55),regB=counterPoint(-8.75,1.21,-1.24),termA=counterPoint(-5.65,1.48,-.87),termB=counterPoint(-5.65,1.43,-1.863),configs={terminal:[termA.x,termA.y,termA.z,termB.x,termB.y,termB.z,37],monitor:[-9.40,1.6,2.3,-10.16,1.6,2.3,38],pump:[7,1.56,-10.65,7,1.5,-11.65,30],register:[regA.x,regA.y,regA.z,regB.x,regB.y,regB.z,Math.max(60,2*Math.atan(.85/Math.max(.8,w.camera.aspect)/1.1)*180/Math.PI)],radio:[15.75,1.06,14.6,16.412,1.03,14.6,28]};
 if(w.device)w.lastDevice=w.device;const cfg=configs[w.lastDevice];if(cfg&&w.focusMix>.001){const q=w.camera.quaternion.clone();w.camera.position.lerp(new T.Vector3(...cfg.slice(0,3)),w.focusMix);w.camera.lookAt(new T.Vector3(...cfg.slice(3,6)));w.camera.quaternion.slerpQuaternions(q,w.camera.quaternion.clone(),w.focusMix);w.camera.fov=T.MathUtils.lerp(71,cfg[6],w.focusMix);w.camera.updateProjectionMatrix();w.hands.visible=false;}else if(!s.binocularActive&&w.camera.fov!==71){w.camera.fov=71;w.camera.updateProjectionMatrix();}updateFieldDevices(w,s,dt);
}
